    pub fn from_key(key: &str) -> Option<Self> {
        let path = key.strip_prefix("minecraft:").unwrap_or(key);
        let by_key = &Self::BY_KEY;
        by_key
            .binary_search_by(|(candidate, _)| candidate.cmp(&path))
            .ok()
            .map(|index| by_key[index].1)
    }

